import stylesText from './nutrition-summary.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { formatTotal, totalsOf, type NutritionTotals } from '../../../../utils/nutrition-totals.js';
import type { LineNutrient, LineNutrition } from '@motivation/shared';

const styles = cssStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `<div class="summary"></div>`;

const MACROS: ReadonlyArray<[LineNutrient, string]> = [['protein_g', 'P'], ['carbs_g', 'C'], ['fat_g', 'F']];
const CHIPS: ReadonlyArray<[LineNutrient, string, string]> = [
    ['protein_g', 'P', 'g'], ['carbs_g', 'C', 'g'], ['fat_g', 'F', 'g'], ['fiber_g', 'Fb', 'g'], ['sugar_g', 'Sugar', 'g'], ['sodium_mg', 'Na', 'mg'],
];

/**
 * Story 420 — a line's or a list's nutrition, one way everywhere (418):
 * - `hero` — big kcal, macros beside it (line editor, totals);
 * - `inline` — "243 kcal · P 22.5 · C 10 · F 12.5" (rows, list totals);
 * - `chips` — every nutrient as a chip, sodium in mg.
 * Unknown reads "?", a partial total "150+?" (story 368). Set `.nutrition` for one line, or
 * `.totals` for a sum.
 */
export class NutritionSummary extends HTMLElement {
    static get observedAttributes() { return ['variant']; }

    private totalsValue: NutritionTotals = totalsOf([]);

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
    }

    set nutrition(value: LineNutrition) { this.totals = totalsOf([value]); }
    set totals(value: NutritionTotals) {
        this.totalsValue = value;
        this.render();
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private render(): void {
        const root = this.shadowRoot!.querySelector('.summary') as HTMLElement;
        const t = this.totalsValue;
        const variant = this.getAttribute('variant') ?? 'inline';
        root.className = `summary ${variant}`;
        const span = (cls: string, text: string) => Object.assign(document.createElement('span'), { className: cls, textContent: text });

        if (variant === 'chips') {
            root.replaceChildren(...CHIPS.map(([n, label, unit]) => {
                const v = formatTotal(t[n]);
                return span('chip', v === '?' ? `${label} ?` : `${label} ${v}${unit}`);
            }));
            return;
        }
        const macros = MACROS.map(([n, label]) => `${label} ${formatTotal(t[n])}`).join(' · ');
        if (variant === 'hero') {
            root.replaceChildren(span('kcal', formatTotal(t.calories)), span('kcal-unit', 'kcal'), span('macros', macros));
            return;
        }
        root.replaceChildren(span('kcal-inline', `${formatTotal(t.calories)} kcal`), span('macros', ` · ${macros}`));
    }
}

if (!customElements.get('nutrition-summary')) {
    customElements.define('nutrition-summary', NutritionSummary);
}
