import stylesText from './line-add-dialog.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { showModalFresh } from '../../../../utils/dialog.js';
import { pickedLine } from '../../../../utils/pick-line.js';
import { HEALTH_EVENTS, createLinePickedEvent, type FoodPickEvent } from '../../health-events.js';
import '../food-picker/food-picker.component.js';
import type { FoodPicker } from '../food-picker/food-picker.component.js';

const styles = cssStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `
    <dialog class="sheet" aria-label="Add food">
        <div class="head">
            <span class="title">Add food</span>
            <button type="button" class="close" aria-label="Close">×</button>
        </div>
    </dialog>
`;

/**
 * Story 422 — "+ Add food" on a list of lines: `<food-picker>` in a sheet, over the editor it adds
 * to, so the edits made so far stay where they are. A food or Open Food Facts product picked comes
 * out as `health:line-picked`, a line at its usual amount; the editor's `addLine()` takes it. The
 * picker is made on the first open: it fetches the slot's frequent foods as it connects, and an
 * editor that never adds anything should not.
 */
export class LineAddDialog extends HTMLElement {
    private picker: FoodPicker | null = null;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        shadow.querySelector('.close')!.addEventListener('click', () => this.dialog.close());
        // A closed sheet keeps its picker: stop a scan it left open, and forget a miss.
        this.dialog.addEventListener('close', () => {
            this.picker?.closeScan();
            this.picker?.showMiss(null);
        });
    }

    /** Open on the slot's frequent foods. */
    open(mealType: string | null): void {
        const picker = this.picker ?? this.makePicker();
        if (mealType) picker.setAttribute('meal-type', mealType);
        else picker.removeAttribute('meal-type');
        showModalFresh(this.dialog);
        picker.focusSearch();
    }

    private makePicker(): FoodPicker {
        const picker = document.createElement('food-picker') as FoodPicker;
        // Story 432: Scan is the picker's own, so the sheet scans without leaving the editor.
        picker.setAttribute('actions', 'scan');
        picker.addEventListener(HEALTH_EVENTS.FOOD_PICK, (e: FoodPickEvent) => {
            e.stopPropagation();
            const { entry, bind } = e.detail;
            // The picker here offers no meals (a list holds foods), so a meal never arrives.
            if (entry.kind === 'meal') return;
            this.dialog.close();
            this.dispatchEvent(createLinePickedEvent({
                line: pickedLine(entry.kind === 'food' ? { kind: 'food', item: entry.item } : { kind: 'off', product: entry.product }),
                bind: bind ?? null,
            }));
        });
        this.dialog.append(picker);
        this.picker = picker;
        return picker;
    }

    private get dialog(): HTMLDialogElement {
        return this.shadowRoot!.querySelector('dialog') as HTMLDialogElement;
    }
}

if (!customElements.get('line-add-dialog')) {
    customElements.define('line-add-dialog', LineAddDialog);
}
