import stylesText from './line-list.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';
import { roundAmount } from '../../../../utils/amount-steps.js';
import { viewNutrition, withAmount, type LineView } from '../../../../utils/line-view.js';
import { totalsOf } from '../../../../utils/nutrition-totals.js';
import {
    HEALTH_EVENTS,
    createLineAddRequestEvent,
    createLinesChangeEvent,
    type AmountChangeEvent,
    type LineAmountChangeEvent,
    type LineRemoveEvent,
} from '../../health-events.js';
import '../line-row/line-row.component.js';
import '../nutrition-summary/nutrition-summary.component.js';
import '../amount-input/amount-input.component.js';
import type { LineRow } from '../line-row/line-row.component.js';
import type { NutritionSummary } from '../nutrition-summary/nutrition-summary.component.js';
import type { AmountInput } from '../amount-input/amount-input.component.js';

const styles = cssStyleSheet(stylesText);

const template = document.createElement('template');
template.innerHTML = `
    <div class="scale" hidden>
        <span class="scale-label">Portion</span>
        <amount-input unit="factor" label="Portion"></amount-input>
    </div>
    <div class="rows" role="list"></div>
    <p class="empty" hidden>Nothing here yet.</p>
    <button type="button" class="add" hidden></button>
    <div class="totals"><nutrition-summary variant="inline"></nutrition-summary></div>
`;

/**
 * Story 420 — a list of lines (418 #1): `<line-row>`s, an optional add button and scale, and
 * the totals. Read-only unless `editable` (steppers) / `removable` (×); `addable` shows
 * "+ {add-label}" (`health:line-add-request`), `scalable` a portion factor. Every edit comes
 * out as ONE `health:lines-change` with the complete list — the editor around it saves that.
 */
export class LineList extends HTMLElement {
    static get observedAttributes() { return ['editable', 'removable', 'addable', 'add-label', 'scalable']; }

    private linesValue: LineView[] = [];
    private factor = 1;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
        // Children set by property below must be upgraded first, or the value lands as an own
        // property that hides their setter.
        customElements.upgrade(shadow);

        shadow.addEventListener(HEALTH_EVENTS.LINE_AMOUNT_CHANGE, (e: Event) => {
            const { key, amount } = (e as LineAmountChangeEvent).detail;
            e.stopPropagation();
            this.change(this.linesValue.map((l) => (l.key === key ? withAmount(l, amount) : l)));
        });
        shadow.addEventListener(HEALTH_EVENTS.LINE_REMOVE, (e: Event) => {
            const { key } = (e as LineRemoveEvent).detail;
            e.stopPropagation();
            this.change(this.linesValue.filter((l) => l.key !== key));
        });
        const scale = shadow.querySelector('.scale amount-input') as AmountInput;
        scale.value = 1;
        scale.addEventListener(HEALTH_EVENTS.AMOUNT_CHANGE, (e: AmountChangeEvent) => {
            e.stopPropagation();
            const ratio = e.detail.value / this.factor;
            this.factor = e.detail.value;
            this.change(this.linesValue.map((l) => withAmount(l, roundAmount(l.amount * ratio))));
        });
        shadow.querySelector('.add')!.addEventListener('click', () => this.dispatchEvent(createLineAddRequestEvent()));
    }

    get lines(): LineView[] { return this.linesValue; }
    /** The list as the editor holds it. Setting it resets the portion factor to ×1. */
    set lines(value: LineView[]) {
        this.linesValue = value;
        this.factor = 1;
        (this.shadowRoot!.querySelector('.scale amount-input') as AmountInput).value = 1;
        this.render();
    }

    /** Every row's amount is an amount — an editor checks this before it saves. */
    allAmountsValid(): boolean {
        return [...this.shadowRoot!.querySelectorAll<LineRow>('line-row')].every((row) => row.amountValid());
    }

    attributeChangedCallback(): void { this.render(); }
    connectedCallback(): void { this.render(); }

    private change(next: LineView[]): void {
        this.linesValue = next;
        this.render();
        this.dispatchEvent(createLinesChangeEvent({ lines: next }));
    }

    private render(): void {
        const shadow = this.shadowRoot!;
        const rows = shadow.querySelector('.rows') as HTMLElement;
        const byKey = new Map([...rows.querySelectorAll<LineRow>('line-row')].map((r) => [r.line?.key, r]));
        const next = this.linesValue.map((line) => {
            const row = byKey.get(line.key) ?? (document.createElement('line-row') as LineRow);
            row.setAttribute('role', 'listitem');
            row.toggleAttribute('editable', this.hasAttribute('editable'));
            row.toggleAttribute('removable', this.hasAttribute('removable'));
            row.line = line;
            return row;
        });
        rows.replaceChildren(...next);
        (shadow.querySelector('.empty') as HTMLElement).hidden = this.linesValue.length > 0;
        const add = shadow.querySelector('.add') as HTMLButtonElement;
        add.hidden = !this.hasAttribute('addable');
        add.textContent = `+ ${this.getAttribute('add-label') ?? 'Add food'}`;
        (shadow.querySelector('.scale') as HTMLElement).hidden = !this.hasAttribute('scalable');
        (shadow.querySelector('nutrition-summary') as NutritionSummary).totals = totalsOf(this.linesValue.map(viewNutrition));
    }
}

if (!customElements.get('line-list')) {
    customElements.define('line-list', LineList);
}
