import type { FoodItem, FoodItemBarcodeMatch, Meal } from '@motivation/shared';
import { HealthService } from '../../../../services/health.service.js';
import { OpenFoodFactsService, type OFFProduct, type OffLookupOutcome } from '../../../../services/openfoodfacts.service.js';
import type { ComponentLogger } from '../../../../utils/component-logger.js';

/**
 * What a scanned barcode turned out to be. `pending` is the scanned code while the library still
 * does not know it — saving can bind it, with consent (story 344): an item-code suggestion
 * (369), an Open Food Facts match through a sibling package (342), or no answer at all (340).
 */
export type ScanResolution =
    | { kind: 'library'; item: FoodItemBarcodeMatch; pending: string | null }
    | { kind: 'product'; product: OFFProduct; pending: string | null }
    | { kind: 'none'; library: 'miss' | 'failed'; off: OffLookupOutcome; status?: number; pending: string };

/** Story 373: the library first, then Open Food Facts — the one lookup both hosts run. */
export async function resolveScannedBarcode(barcode: string, log: ComponentLogger): Promise<ScanResolution> {
    // Story 339: a library FAILURE is not a library MISS, and OFF may still answer.
    let library: 'miss' | 'failed' = 'miss';
    try {
        const item = await HealthService.findFoodItemByBarcode(barcode);
        if (item) return { kind: 'library', item, pending: item.matched_by === 'item_code' ? barcode : null };
    } catch (err) {
        library = 'failed';
        log.warn('barcode library lookup failed', { barcode, error: String(err) });
    }
    const { product, outcome, status } = await OpenFoodFactsService.lookupBarcode(barcode);
    if (product) return { kind: 'product', product, pending: outcome === 'found_by_item_code' ? barcode : null };
    return { kind: 'none', library, off: outcome, status, pending: barcode };
}

/** What a search writes its answers to — `<food-picker>`'s list (story 420). */
export interface FoodSearchSink {
    libraryItems: FoodItem[];
    offItems: OFFProduct[];
    meals: Meal[];
    showLoadMore: boolean;
    appendOffItems(products: OFFProduct[]): void;
    clear(): void;
    showEmpty(message: string): void;
}

/** Where a search shows itself. Getters, because the host's children upgrade after it connects. */
export interface FoodSearchSurface {
    results(): FoodSearchSink;
    loading(): HTMLElement;
    error(): HTMLElement;
}

function isAbort(err: unknown): boolean {
    return (err as { name?: unknown } | null)?.name === 'AbortError';
}

function rawError(err: unknown): string {
    return err instanceof Error ? `${err.name}: ${err.message}` : String(err);
}

/**
 * Story 373 (pwa-nutrition-17) — the one food search, for `<food-log>` and
 * `<meal-ingredient-picker>`. Each had its own copy and they drifted: 372's "Searching…" and
 * meal-wipe fixes reached only food-log, food-log swallowed a failed library leg while the
 * picker warned, and the two answered a failed Load More differently.
 *
 * - `search` (Enter): the library, saved meals when the host offers them, and Open Food Facts.
 * - `searchLocal` (typing): the library and meals; it supersedes a pending `search`, so it stops
 *   that search's OFF leg and its "Searching…".
 * - `loadMore`: the next OFF page of the last `search`.
 * - `stopOff`: abort the OFF leg without superseding — a pick leaves the results to come back to.
 * - `reset`: supersede everything and clear.
 *
 * A superseded leg drops its answer, and an aborted OFF request is "not done", never "found
 * nothing" (story 372).
 */
export class FoodSearchPipeline {
    private readonly surface: FoodSearchSurface;
    private readonly log: ComponentLogger;
    private readonly withMeals: boolean;
    private seq = 0;
    private offAbort: AbortController | null = null;
    private query = '';
    private offPage = 1;

    constructor(surface: FoodSearchSurface, log: ComponentLogger, options: { meals: boolean }) {
        this.surface = surface;
        this.log = log;
        this.withMeals = options.meals;
    }

    search(query: string): void {
        if (query.length < 2) return;
        this.query = query;
        this.offPage = 1;
        const results = this.surface.results();
        const loading = this.surface.loading();
        const error = this.surface.error();
        this.stopOff();
        loading.hidden = false;
        error.hidden = true;
        results.clear();

        const seq = ++this.seq;
        const offAbort = new AbortController();
        this.offAbort = offAbort;
        const legs = {
            library: { done: false, failed: false, count: 0 },
            off: { done: false, failed: false, count: 0 },
            meals: { done: !this.withMeals, count: 0, error: null as string | null },
        };

        const finalize = () => {
            if (seq !== this.seq || !legs.library.done || !legs.off.done || !legs.meals.done) return;
            loading.hidden = true;
            if (this.offAbort === offAbort) this.offAbort = null;

            if (legs.library.failed && legs.off.failed) {
                // Story 339: both backends down is a different fact from "no such food".
                this.log.error('food search failed on both backends', { query });
                error.textContent = 'Search failed. Please try again.';
                error.hidden = false;
                return;
            }
            if (legs.meals.error !== null) {
                error.textContent = `Saved meals search failed: ${legs.meals.error}`;
                error.hidden = false;
            }
            // Story 372: a saved meal is a result too — `showEmpty` replaced its row.
            if (legs.library.count === 0 && legs.off.count === 0 && legs.meals.count === 0) {
                // Story 339: which side came back EMPTY and which FAILED separates a gap in the
                // data from an outage.
                this.log.warn('food search found nothing', {
                    query,
                    library: legs.library.failed ? 'failed' : 'empty',
                    off: legs.off.failed ? 'failed' : 'empty',
                });
                results.showEmpty('No products found');
            }
        };

        void HealthService.searchFoodItems(query)
            .then((items) => {
                if (seq !== this.seq) return;
                legs.library.count = items.length;
                if (items.length > 0) results.libraryItems = items;
            })
            .catch((err) => {
                if (seq !== this.seq) return;
                legs.library.failed = true;
                this.log.warn('library search failed', { query, error: err instanceof Error ? err.message : String(err) });
            })
            .finally(() => {
                if (seq !== this.seq) return;
                legs.library.done = true;
                finalize();
            });

        if (this.withMeals) {
            // The search still works without the meals, but a failed lookup says so (story 387).
            void HealthService.searchMeals(query)
                .then((meals) => {
                    if (seq !== this.seq) return;
                    legs.meals.count = meals.length;
                    if (meals.length > 0) results.meals = meals;
                })
                .catch((err) => {
                    if (seq !== this.seq) return;
                    legs.meals.error = rawError(err);
                    this.log.warn('saved meals search failed', { query, error: legs.meals.error });
                })
                .finally(() => {
                    legs.meals.done = true;
                    finalize();
                });
        }

        void OpenFoodFactsService.searchFood(query, { signal: offAbort.signal, page: 1 })
            .then((page) => {
                if (seq !== this.seq) return;
                legs.off.count = page.items.length;
                legs.off.done = true;
                this.offPage = page.page;
                if (page.items.length > 0) {
                    results.offItems = page.items;
                    results.showLoadMore = page.page < page.pageCount;
                }
                finalize();
            })
            .catch((err) => {
                // Aborted is not done: whatever aborted it owns the screen now.
                if (seq !== this.seq || isAbort(err)) return;
                legs.off.failed = true;
                legs.off.done = true;
                this.log.warn('OFF search failed', { query, error: err instanceof Error ? err.message : String(err) });
                finalize();
            });
    }

    async searchLocal(query: string): Promise<void> {
        if (query.length < 2) return;
        const results = this.surface.results();
        this.surface.error().hidden = true;
        // Story 372: this supersedes a search still waiting on OFF, whose callbacks now drop
        // their answers — so nothing else would hide "Searching…".
        this.stopOff();
        this.surface.loading().hidden = true;

        const seq = ++this.seq;
        const error = this.surface.error();
        // Story 387 (pwa-nutrition-13): typing said nothing when either lookup failed.
        let mealsError: string | null = null;
        try {
            const [items, meals] = await Promise.all([
                HealthService.searchFoodItems(query),
                this.withMeals
                    ? HealthService.searchMeals(query).catch((err: unknown) => { mealsError = rawError(err); return []; })
                    : Promise.resolve([]),
            ]);
            if (seq !== this.seq) return;
            results.clear();
            if (meals.length > 0) results.meals = meals;
            if (items.length > 0) results.libraryItems = items;
            if (mealsError !== null) {
                this.log.warn('saved meals search failed', { query, error: mealsError });
                error.textContent = `Saved meals search failed: ${mealsError}`;
                error.hidden = false;
            }
        } catch (err) {
            if (seq !== this.seq) return;
            this.log.warn('local search failed', { query, error: rawError(err) });
            error.textContent = `Library search failed: ${rawError(err)}`;
            error.hidden = false;
        }
    }

    async loadMore(): Promise<void> {
        const query = this.query;
        if (!query) return;
        const results = this.surface.results();
        const seq = this.seq;
        const offAbort = new AbortController();
        this.offAbort = offAbort;
        try {
            const page = await OpenFoodFactsService.searchFood(query, { signal: offAbort.signal, page: this.offPage + 1 });
            if (seq !== this.seq) return;
            this.offPage = page.page;
            results.appendOffItems(page.items);
            results.showLoadMore = page.page < page.pageCount;
        } catch (err) {
            if (seq !== this.seq || isAbort(err)) return;
            // Story 370: said, and the button stays so the next tap retries.
            this.log.warn('OFF load-more failed', { query, error: err instanceof Error ? err.message : String(err) });
            results.showLoadMore = true;
            const error = this.surface.error();
            error.textContent = `Loading more results failed: ${err instanceof Error ? err.message : String(err)}`;
            error.hidden = false;
        } finally {
            if (this.offAbort === offAbort) this.offAbort = null;
        }
    }

    stopOff(): void {
        this.offAbort?.abort();
        this.offAbort = null;
    }

    reset(): void {
        this.stopOff();
        this.seq++;
        this.surface.results().clear();
        this.surface.loading().hidden = true;
        this.surface.error().hidden = true;
    }
}
